19	// Literal represents a literal value in an expression.
20	type Literal struct {
21		val any
22	}
23	
24	func (l *Literal) expr()  {}
25	func (l *Literal) value() {}
26	
27	// Val returns the underlying value.
28	func (l *Literal) Val() any { return l.val }
29	
30	// Lit creates a literal value from any Go value.
31	func Lit(v any) *Literal {
32		return &Literal{val: v}
33	}
