208	// Generates: strings.Contains(parameter.name, "substr")
209	type StringContainsCondition struct {
210		baseCondition
211		paramName string
212		substr    string
213	}
214	
215	// ParamName returns the parameter name being checked.
216	func (c *StringContainsCondition) ParamName() string { return c.paramName }
217	
218	// Substr returns the substring to check for.
219	func (c *StringContainsCondition) Substr() string { return c.substr }
