242	// Generates: strings.HasPrefix(parameter.name, "prefix")
243	type StringStartsWithCondition struct {
244		baseCondition
245		paramName string
246		prefix    string
247	}
248	
249	// ParamName returns the parameter name being checked.
250	func (c *StringStartsWithCondition) ParamName() string
