// chained-guard syntax (`parameter["x"] != _|_ if <expr>`). Such operands must
// not be wrapped in parentheses or joined with && inside a compound condition.
func isChainedGuard(cond Condition) bool {
	switch cond.(type) {
	case *LenCondition, *ArrayContainsCondition:
		return true
	default:
		return false
	}
}

// joinAndConditions joins conditions for an AND-style compound. When any
// sub-condition uses chained-guard syntax it joins with " if "; otherwise " && ".
func (g *CUEGenerator) joinAndConditions(conds []Condition) string {
	chained := false
	for _, c := range conds {
		if isChainedGuard(c) {
			chained = true
			break
		}
	}
	sep := " && "
	if chained {
		sep = " if "
	}
	parts := make([]string, len(conds))
	for i, c := range conds {
		parts[i] = g.conditionToCUE(c)
	}
	return strings.Join(parts, sep)
}

