// writeValidatorBody writes the `name: { "message": true; if fail { "message": false } }`
// block. An AbsentOrEmpty fail condition emits one false-assignment block per branch.
func (g *CUEGenerator) writeValidatorBody(sb *strings.Builder, v *Validator, name string, depth int) {
	indent := strings.Repeat(g.indent, depth)
	inner := strings.Repeat(g.indent, depth+1)

	sb.WriteString(fmt.Sprintf("%s%s: {\n", indent, name))
	sb.WriteString(fmt.Sprintf("%s%q: true\n", inner, v.Message()))
	if v.FailCondition() != nil {
		g.emitGuardedBlocks(sb, v.FailCondition(), inner, func() {
			sb.WriteString(fmt.Sprintf("%s\t%q: false\n", inner, v.Message()))
		})
	}
	sb.WriteString(fmt.Sprintf("%s}\n", indent))
