func TestScratchChainedGuard(t *testing.T) {
	g := NewCUEGenerator()

	arr := StringList("tags")
	m := Map("config")
	s := String("name")

	checks := []struct {
		name string
		cond Condition
		want string
	}{
		{"str.LenEq", s.LenEq(5), `parameter["name"] != _|_ if len(parameter["name"]) == 5`},
		{"arr.LenGt", arr.LenGt(0), `parameter["tags"] != _|_ if len(parameter["tags"]) > 0`},
		{"arr.Contains", arr.Contains("gpu"), `parameter["tags"] != _|_ if list.Contains(parameter["tags"], "gpu")`},
		{"map.HasKey", m.HasKey("debug"), `parameter["config"] != _|_ && parameter["config"].debug != _|_`},
		{"arr.IsNotEmpty", arr.IsNotEmpty(), `parameter["tags"] != _|_ if len(parameter["tags"]) > 0`},
		{"AllConditions-chained", AllConditions(s.IsSet(), arr.IsNotEmpty()), `parameter["name"] != _|_ if parameter["tags"] != _|_ if len(parameter["tags"]) > 0`},
		{"AllConditions-plain", AllConditions(s.IsSet(), m.HasKey("a")), `parameter["name"] != _|_ && parameter["config"] != _|_ && parameter["config"].a != _|_`},
		{"Or-chained", Or(arr.IsNotEmpty(), s.IsSet()), `parameter["tags"] != _|_ if len(parameter["tags"]) > 0 || parameter["name"] != _|_`},
		{"And-chained", And(s.IsSet(), arr.IsNotEmpty()), `parameter["name"] != _|_ if parameter["tags"] != _|_ if len(parameter["tags"]) > 0`},
	}
	for _, c := range checks {
		got := g.conditionToCUE(c.cond)
		if got != c.want {
			t.Errorf("%s:\n got=%q\nwant=%q", c.name, got, c.want)
		}
	}

	// IsEmpty returns AbsentOrEmpty
	if _, ok := arr.IsEmpty().(*AbsentOrEmptyCondition); !ok {
		t.Errorf("arr.IsEmpty not AbsentOrEmpty: %T", arr.IsEmpty())
	}
	if _, ok := arr.LenEq(0).(*AbsentOrEmptyCondition); !ok {
		t.Errorf("arr.LenEq(0) not AbsentOrEmpty")
	}
	skm := StringKeyMap("labels")
	if _, ok := skm.HasKey("x").(*MapHasKeyCondition); !ok {
		t.Errorf("skm.HasKey not MapHasKeyCondition")
	}

	// SetIf with AbsentOrEmpty → two if blocks
	res := NewResource("apps/v1", "Deployment").
		SetIf(arr.IsEmpty(), "spec.empty", Lit("yes"))
	var sb strings.Builder
	g.writeResourceOutput(&sb, "output", res, nil, 1)
	out := sb.String()
	t.Logf("SETIF OUTPUT:\n%s", out)
	if !strings.Contains(out, `parameter["tags"] == _|_`) || !strings.Contains(out, `parameter["tags"] != _|_ if len(parameter["tags"]) == 0`) {
		t.Errorf("SetIf AbsentOrEmpty missing branches")
	}

	// bracket-access SetIf single condition
	res2 := NewResource("v1", "ConfigMap").
		SetIf(s.IsSet(), "data[my-key]", Lit("v"))
	var sb2 strings.Builder
	g.writeResourceOutput(&sb2, "output", res2, nil, 1)
	t.Logf("BRACKET SETIF:\n%s", sb2.String())

	// bracket-access unconditional Set nested children
	res3 := NewResource("v1", "ConfigMap").
		Set("metadata.annotations[my.key/x].nested", Lit("v"))
	var sb3 strings.Builder
	g.writeResourceOutput(&sb3, "output", res3, nil, 1)
	t.Logf("BRACKET NESTED:\n%s", sb3.String())

	// validator FailWhen(IsEmpty)
	v := Validate("tags must not be empty").FailWhen(arr.IsEmpty()).WithName("_validateTags")
	var sb4 strings.Builder
	g.writeValidator(&sb4, v, 1)
	t.Logf("VALIDATOR FAILWHEN:\n%s", sb4.String())

	// validator OnlyWhen(IsEmpty)
	v2 := Validate("msg").OnlyWhen(arr.IsEmpty()).FailWhen(s.IsSet()).WithName("_v")
	var sb5 strings.Builder
	g.writeValidator(&sb5, v2, 1)
	t.Logf("VALIDATOR ONLYWHEN:\n%s", sb5.String())

	// OneOf optional+default
	comp := NewComponent("t").Params(OneOf("kind").Optional().Default("a").Variants(Variant("a"), Variant("b")))
	pc := g.GenerateParameterSchema(comp)
	t.Logf("ONEOF OPT+DEF:\n%s", pc)
	if !strings.Contains(pc, `kind: *"a" | "b"`) {
		t.Errorf("OneOf opt+default should have no ? marker")
	}
	comp2 := NewComponent("t").Params(OneOf("kind").Optional().Variants(Variant("a"), Variant("b")))
	pc2 := g.GenerateParameterSchema(comp2)
	if !strings.Contains(pc2, `kind?:`) {
		t.Errorf("OneOf opt-only should have ? marker: %s", pc2)
	}

	// RequiredImports
	if imps := StringList("x").MinItems(1).RequiredImports(); len(imps) != 1 || imps[0] != "list" {
		t.Errorf("RequiredImports minItems: %v", imps)
	}
	if imps := StringList("x").MinItems(1).MaxItems(5).RequiredImports(); len(imps) != 1 {
		t.Errorf("RequiredImports both should be once: %v", imps)
	}
	if imps := StringList("x").RequiredImports(); imps != nil {
		t.Errorf("RequiredImports none should be nil: %v", imps)
	}
}
